TYPE GateState :
(
    IDLE    := 0,
    OPENING := 1,
    CLOSING := 2,
    FAULT   := 3
);
END_TYPE

FUNCTION_BLOCK FB
VAR_INPUT
    openBtn    : BOOL;
    closeBtn   : BOOL;
    openLimit  : BOOL;
    closeLimit : BOOL;
    obstacle   : BOOL;
END_VAR
VAR_OUTPUT
    motorUp   : BOOL;
    motorDown : BOOL;
    errorFlag : BOOL;
END_VAR
VAR
    prevOpenBtn  : BOOL := FALSE;
    prevCloseBtn : BOOL := FALSE;
    prevBoth     : BOOL := FALSE;
    state        : GateState := IDLE;
    openRising   : BOOL;
    closeRising  : BOOL;
    bothRising   : BOOL;
END_VAR

    // ----- Edge detection -----
    openRising  := openBtn AND NOT prevOpenBtn;
    closeRising := closeBtn AND NOT prevCloseBtn;
    bothRising  := (openBtn AND closeBtn) AND NOT prevBoth;

    // Update previous button states for next cycle
    prevOpenBtn  := openBtn;
    prevCloseBtn := closeBtn;
    prevBoth     := (openBtn AND closeBtn);

    // ----- State machine -----
    CASE state OF
        IDLE :
            motorUp   := FALSE;
            motorDown := FALSE;
            errorFlag := FALSE;

            // Simultaneous press is reserved for reset, ignore start commands
            IF NOT bothRising THEN
                IF openRising AND NOT openLimit THEN
                    state    := OPENING;
                    motorUp  := TRUE;
                ELSIF closeRising AND NOT closeLimit THEN
                    state    := CLOSING;
                    motorDown := TRUE;
                END_IF
            END_IF

        OPENING :
            motorUp   := TRUE;
            motorDown := FALSE;

            IF openLimit THEN
                state    := IDLE;
                motorUp  := FALSE;
            ELSIF obstacle THEN
                state      := FAULT;
                motorUp    := FALSE;
                errorFlag  := TRUE;
            END_IF

        CLOSING :
            motorUp   := FALSE;
            motorDown := TRUE;

            IF closeLimit THEN
                state     := IDLE;
                motorDown := FALSE;
            ELSIF obstacle THEN
                state     := OPENING;
                motorDown := FALSE;
                motorUp   := TRUE;
            END_IF

        FAULT :
            motorUp   := FALSE;
            motorDown := FALSE;
            errorFlag := TRUE;

            // Reset only on simultaneous button press when obstacle is cleared
            IF bothRising AND NOT obstacle THEN
                state      := IDLE;
                errorFlag  := FALSE;
            END_IF
    END_CASE

END_FUNCTION_BLOCK
